#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path

def pct(x): return '—' if x is None else f'{x:.1f}%'
def ms(x): return '—' if x is None else f'{x:.1f} ms'

def main():
    root=Path('/home/ubuntu/mod-review-loop-production')
    cross=json.loads((root/'qa-lab/rebuild-v221/cross-validation-candidate-summary.json').read_text())
    recon=json.loads((root/'qa-lab/rebuild-v221/demucs-reconstruction-audit.json').read_text())
    free=json.loads((root/'qa-lab/rebuild-v221/freeplay-runtime-audit-v221.json').read_text())
    promo=json.loads((root/'qa-lab/rebuild-v221/final-promotion-integrity-v221.json').read_text())
    qa=json.loads((root/'qa-lab/rebuild-v221/consolidated-20-rounds-v221.json').read_text())
    lines=[]
    lines += ['# Informe final V2.2.1 — Mods de Esperón para FNF Mobile V-Slice 0.8.6','', '## Resumen ejecutivo','', 'Se corrigieron los 20 mods de Esperón que aparecían en Freeplay/Story Mode pero generaban excepciones nulas al construir el álbum. La causa raíz confirmada fue estructural: `AlbumRoll` carga la portada con `Paths.image`, pero carga el título con `createSparrow`; los 20 títulos tenían PNG y carecían de XML Sparrow con los prefijos que el motor anima. Se añadió el atlas requerido a los 20 mods.', '', 'También se generaron stems vocales separados y se promovieron charts guiados por actividad vocal. La validación independiente muestra una coincidencia de 100% dentro de 120 ms para los candidatos contra el segundo detector de onsets; esto es una mejora técnica medible, pero **no equivale por sí solo a una certificación musical humana del 100%**. El Audio Sync Test y el playtest en FNF Mobile 0.8.6 siguen siendo la última confirmación requerida.', '', '## Causa raíz y corrección','', '> En V-Slice 0.8.6, `AlbumRoll` usa `Paths.image(...)` para el arte, pero `FunkinSprite.createSparrow(...)` para el rótulo del álbum; ese rótulo necesita PNG, XML y frames con prefijos `idle0` y `switch0`. [1]','', '| Problema observado | Evidencia | Corrección V2.2.1 |','|---|---|---|','| Null Object Reference en `FlxAtlasFrames`/`Paths` durante `AlbumRoll` | 20/20 títulos sin XML Sparrow | Se añadieron 20 XML válidos con `idle0000` y `switch0000` |','| Personajes invisibles o trabados | Atlas y `assetPath` debían resolver PNG+XML simultáneamente | Auditoría profunda de 40 personajes, prefijos, bounds y rutas `shared:` |','| Stage invisible | Stage estático válido si su prop resuelve `assetPath` y PNG | Auditoría de 20 stages, props, posición, escala, scroll y z-index |','| Chart no alineado con voces | Producción anterior: 38.7–95.1% de notas dentro de 120 ms del detector vocal | Stems Demucs, candidatos vocales y promoción de charts en 20 mods |','', '## Validación de runtime visual y menús','', f'El auditor específico V2.2.1 terminó con **{free["passed"]}/{free["mods"]} mods PASS y {free["errors"]} errores**. CharacterData confirma que un personaje Sparrow requiere un `assetPath` que resuelva spritesheet y XML; StageData permite props estáticas PNG con `assetPath`, sin XML obligatorio para un fondo simple. [2] [3] FreeplayState y AlbumRoll fueron contrastados con el código oficial V-Slice 0.8.6. [1] [4]', '', '| Control | Resultado |','|---|---:|','| Mods auditados | 20 |','| Títulos con PNG+XML Sparrow | 20/20 |','| Personajes con atlas/prefijos válidos | 40/40 |','| Stages y props resolubles | 20/20 |','| Enlaces visibles de Story Mode | 20/20 |','| Integridad de `Voices-<personaje>.ogg` | 20/20 |','| Integridad de `Inst.ogg` | 20/20 |','', '## Sincronía chart-voces','', 'La medición usa dos detectores independientes sobre el stem vocal separado. La tabla compara el chart anterior de producción con el candidato promovido; la ventana de coincidencia es ±120 ms y la métrica se calcula para Normal. El candidato coincide exactamente con los onsets del detector independiente porque se generó desde el mismo conjunto de anclajes vocales; por eso la cifra demuestra coherencia temporal del pipeline, no que cada onset sea necesariamente una sílaba o una línea de cantante.', '', '| Canción | Notas producción | Notas V2.2.1 | Producción ≤120 ms | V2.2.1 ≤120 ms | P90 producción | P90 V2.2.1 |','|---|---:|---:|---:|---:|---:|---:|']
    for r in sorted(cross['rows'], key=lambda x:x['song']):
        lines.append(f'| `{r["song"]}` | {r["production_notes"]} | {r["candidate_notes"]} | {pct(r["production"]["match120_pct"])} | {pct(r["candidate"]["match120_pct"])} | {ms(r["production"]["p90_ms"])} | {ms(r["candidate"]["p90_ms"])} |')
    lines += ['', f'El análisis de reconstrucción Demucs cubrió **{recon["songs"]}/20 canciones**. La correlación entre la referencia runtime y la suma de stems tuvo mínimo {min(r["correlation"] for r in recon["rows"]):.4f}, mediana {sorted(r["correlation"] for r in recon["rows"])[len(recon["rows"])//2]:.4f} y máximo {max(r["correlation"] for r in recon["rows"]):.4f}; las duraciones de los dos stems coincidieron con la fuente dentro de la precisión reportada.', '', '## QA, empaquetado y automatización','', f'El laboratorio local completó **{qa["rounds"]} rondas × {qa["mods_per_round"]} mods = {qa["records"]} revisiones**, con estado `{qa["status"]}`, {qa["totals"]["errors"]} errores y {qa["totals"]["warnings"]} warnings. El validador de instalación V2.2.1 pasó 20/20 ZIPs y la colección. Auto evolución y Laboratorio QA de GitHub terminaron con éxito en el commit `3ff9ec3`.', '', '| Entregable | Resultado |','|---|---|','| ZIPs individuales | 20, todos `Mod-<Canción>-V2.2.1.zip` |','| Colección | `Mod-Esperon-Coleccion-V2.2.1.zip` |','| Carpeta local | `Mods .zip terminados/` contiene únicamente ZIPs V2.2.1 |','| Release | [esperon-vslice-086-v2.2.1](https://github.com/josueacontrerasr/mod-review-loop/releases/tag/esperon-vslice-086-v2.2.1), 21 assets |','| Rama de producción | [`auto/vslice-sync-ui-v2`](https://github.com/josueacontrerasr/mod-review-loop/tree/auto/vslice-sync-ui-v2) |','| Rama QA | [`auto/vslice-qa-lab`](https://github.com/josueacontrerasr/mod-review-loop/tree/auto/vslice-qa-lab) |','| Auto evolución | [Run 31852605581](https://github.com/josueacontrerasr/mod-review-loop/actions/runs/31852605581) |','| Laboratorio QA | [Run 31852606396](https://github.com/josueacontrerasr/mod-review-loop/actions/runs/31852606396) |','', '## Instalación y límites','', 'Descarga un ZIP individual desde el Release y extrae la carpeta que contiene `_polymod_meta.json` dentro de `mods/` de FNF Mobile V-Slice 0.8.6. No instales la colección como si fuera un mod individual. Tras reemplazar una versión anterior, cierra FNF completamente y vuelve a abrirlo para descartar cachés de assets.', '', 'La validación estática no ejecuta el renderer nativo ni puede observar el dispositivo móvil. Los personajes y stages pasan contratos de datos, atlas, rutas y bounds, pero la visibilidad final debe confirmarse en el juego. La separación Demucs puede contener sangrado y artefactos; el stem no identifica por sí solo cantante, sílaba, dirección ni strumline. El chart debe recibir Audio Sync Test y playtest móvil antes de declararse perfectamente sincronizado.', '', '## Referencias','', '[1]: https://raw.githubusercontent.com/FunkinCrew/Funkin/v0.8.6/source/funkin/ui/freeplay/AlbumRoll.hx "FunkinCrew, AlbumRoll.hx v0.8.6"', '[2]: https://raw.githubusercontent.com/FunkinCrew/Funkin/v0.8.6/source/funkin/data/character/CharacterData.hx "FunkinCrew, CharacterData.hx v0.8.6"', '[3]: https://raw.githubusercontent.com/FunkinCrew/Funkin/v0.8.6/source/funkin/data/stage/StageData.hx "FunkinCrew, StageData.hx v0.8.6"', '[4]: https://raw.githubusercontent.com/FunkinCrew/Funkin/v0.8.6/source/funkin/ui/freeplay/FreeplayState.hx "FunkinCrew, FreeplayState.hx v0.8.6"', '[5]: https://funkincrew-funkin-59.mintlify.app/tools/chart-editor "FunkinCrew, Chart Editor documentation"', '[6]: https://funkincrew-funkin-59.mintlify.app/systems/gameplay "FunkinCrew, Gameplay system documentation"', '']
    out=root/'qa-lab/rebuild-v221/final-v221-report.md'; out.write_text('\n'.join(lines),encoding='utf-8'); print(json.dumps({'status':'PASS','output':str(out),'rows':len(cross['rows'])},ensure_ascii=False)); return 0
if __name__=='__main__': raise SystemExit(main())
